create table public.orders (id uuid primary key default gen_random_uuid(),reference text not null unique default ('ORD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),customer_id uuid references public.profiles(id),customer_name text not null,customer_email text not null,customer_phone text not null,total_paise integer not null check(total_paise>=0),currency text not null default 'INR',payment_status text not null default 'pending' check(payment_status in('pending','paid','failed','refunded')),fulfillment_status text not null default 'pending' check(fulfillment_status in('pending','processing','shipped','completed','cancelled')),shipping_address jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id),product_title text not null,quantity integer not null check(quantity>0),unit_price_paise integer not null check(unit_price_paise>=0),created_at timestamptz not null default now());
create index orders_customer_idx on public.orders(customer_id,created_at desc);create index order_items_order_idx on public.order_items(order_id);
create trigger orders_updated_at before update on public.orders for each row execute procedure private.set_updated_at();
alter table public.orders enable row level security;alter table public.order_items enable row level security;
create policy "customers read own orders" on public.orders for select to authenticated using(customer_id=(select auth.uid()));create policy "staff manage orders" on public.orders for all to authenticated using((select private.is_staff())) with check((select private.is_staff()));
create policy "customers read own order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=(select auth.uid())));create policy "staff manage order items" on public.order_items for all to authenticated using((select private.is_staff())) with check((select private.is_staff()));
grant select on public.orders,public.order_items to authenticated;grant insert,update,delete on public.orders,public.order_items to authenticated;
